{
  "interpretation": {
    "name": "Line2NutrunnerTightening",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2 of line 2, tighten the fasteners, then evaluate, record and return the tool.",
    "constraints": [
      "The operator asked for a fixed target torque of 210 N*m instead of the MES program. Numeric process values must not appear in a Recipe (E4), so this value is not placed in the Recipe.",
      "The tool must be reserved, and the lease renewed before each physical use (E1, E6).",
      "transport-tool must run on the executor agvexecutor (E2).",
      "The tool must be at st2 before configure-tool and tighten-fasteners (E3).",
      "The tightening must be evaluated and recorded (E5).",
      "The reservation must be released at the end."
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "Single execution for the current request.",
    "requested_capabilities": [],
    "omit_services": ["get-program"]
  },
  "recipe": {
    "name": "line2-nutrunner-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {"name": "to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["fasten"], "dep": ["program", "reserve", "to-station"], "executor": null, "params": {}},
          {"name": "fasten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve", "to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "quality",
        "next": "finish",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["fasten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["fasten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {"name": "to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
